def bbox(a):
 y,x=np.where(a[:,:,3]>=128);return [int(x.min()),int(y.min()),int(x.max()+1),int(y.max()+1)]
def footmetric(a):
 sub=a[138:155,98:132,3]>=128;y,x=np.where(sub);return {'roi':[98,138,132,155],'pixelCount':int(len(x)),'centroid':[float(x.mean()+98),float(y.mean()+138)],'bottom':int(y.max()+138),'qualification':'Coarse fixed presumed-foot alpha ROI, not anatomical toe tracking'}
eye=[116,90,130,106];mask=np.ones((192,192),bool);mask[eye[1]:eye[3],eye[0]:eye[2]]=False
# Compare visible RGB after compositing, ignoring arbitrary RGB under alpha0.
def comp(a,bg):
 al=a[:,:,3:4].astype(float)/255;return np.round(a[:,:,:3]*al+np.array(bg)[None,None,:]*(1-al)).astype('uint8')
ca,cc=comp(aa,[213,220,195]),comp(ac,[213,220,195]);diff=np.max(np.abs(ca.astype(int)-cc.astype(int)),axis=2);visible=(aa[:,:,3]>0)|(ac[:,:,3]>0)
overlap=np.logical_and(aa[:,:,3]>=128,ac[:,:,3]>=128).sum()/np.logical_or(aa[:,:,3]>=128,ac[:,:,3]>=128).sum()
fa,fc=footmetric(aa),footmetric(ac);delta=np.linalg.norm(np.array(fa['centroid'])-fc['centroid'])/1.1
